// Sub-component for the massive cartoony dollar sign
const DollarSymbol: React.FC<{ moneyColor: string; outlineColor: string }> = ({
  moneyColor,
  outlineColor,
}) => (
  <div
    style={{
      fontFamily: luckiestFamily,
      fontSize: "160px",
      color: moneyColor,
      WebkitTextStroke: `10px ${outlineColor}`,
      textShadow: `8px 8px 0px ${outlineColor}`,
      lineHeight: 1,
      padding: "20px",
    }}
  >
    $
  </div>
);

const MoneyExplosion: React.FC<MoneyExplosionProps> = ({
  backgroundColor = "#ffeb3b",
  transparentBackground = false,
  durationInSeconds = 2,
  particleCount = 50,
  moneyColor = "#4ade80",
  outlineColor = "#14532d",
  burstColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Pre-calculate randomized particles
  const particles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      // 40% chance of being a full bill, 60% chance of being a big dollar sign
      const isBill = random(`type-${i}`) > 0.6;
      
      // Full 360 spread
      const angle = random(`angle-${i}`) * Math.PI * 2;
      
      // Distance needs to be large enough to clear a 1080x1920 screen (hypotenuse from center is ~1101px)
      // Adding a base distance of 1400px ensures it fully exits even on diagonals
      const distance = 1400 + random(`dist-${i}`) * 1200;
      
      // 3D Tumbling and Spinning speeds
      const spinZ = (random(`spinZ-${i}`) - 0.5) * 1200;
      const spinX = (random(`spinX-${i}`) - 0.5) * 1440;
      const spinY = (random(`spinY-${i}`) - 0.5) * 1440;
      
      // Varied scaling for depth and variety
      const scale = 0.4 + random(`scale-${i}`) * 1.2;
      
      // A very tight delay for the "pop" effect (0 to 3 frames max)
      const delay = random(`delay-${i}`) * 3;

      return { isBill, angle, distance, spinZ, spinX, spinY, scale, delay };
    });
  }, [particleCount]);

  // Initial Impact Burst Lines (Flash effect)
  const burstProgress = interpolate(frame, [0, Math.floor(fps * 0.4)], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  
  const burstOpacity = interpolate(
    frame,
    [0, Math.floor(fps * 0.2), Math.floor(fps * 0.4)],
    [1, 1, 0],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        perspective: "1200px",
        overflow: "hidden",
      }}
    >
      {/* Background Impact Starburst */}
      {burstOpacity > 0 && (
        <AbsoluteFill
          style={{ justifyContent: "center", alignItems: "center", opacity: burstOpacity }}
        >
          {Array.from({ length: 12 }).map((_, i) => {
            const angle = (i / 12) * 360;
            return (
              <AbsoluteFill
                key={`burst-${i}`}
                style={{
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `rotate(${angle}deg)`,
                }}
              >
                <div
                  style={{
                    width: 24,
                    height: 400,
                    backgroundColor: burstColor,
                    borderRadius: 12,
                    // Shoot outwards and stretch/shrink
                    transform: `translateY(-${300 + burstProgress * 600}px) scaleY(${1 - burstProgress})`,
                    transformOrigin: "bottom center",
                  }}
                />
              </AbsoluteFill>
            );
          })}
        </AbsoluteFill>
      )}

      {/* Explosive Money Particles */}
      {particles.map((p, i) => {
        // Offset frame for individual particle start time
        const pFrame = Math.max(0, frame - p.delay);

        // Spring for initial "pop" bounce scale
        const currentScale =
          frame < p.delay
            ? 0
            : spring({
                fps,
                frame: pFrame,
                config: { damping: 12, mass: 0.6, stiffness: 180 },
              }) * p.scale;

        // Quadratic easing out for the explosive distance shot
        const flyProgress = interpolate(
          pFrame,
          [0, fps * durationInSeconds],
          [0, 1],
          {
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.quad),
          }
        );

        // Calculate radial coordinates
        const x = Math.cos(p.angle) * p.distance * flyProgress;
        const y = Math.sin(p.angle) * p.distance * flyProgress;

        // Calculate dynamic rotations
        const rotZ = p.spinZ * flyProgress;
        const rotX = p.spinX * flyProgress;
        const rotY = p.spinY * flyProgress;

        return (
          <AbsoluteFill
            key={i}
            style={{
              justifyContent: "center",
              alignItems: "center",
              // Apply movement and tumbling 3D effect
              transform: `translate(${x}px, ${y}px) rotateZ(${rotZ}deg) rotateX(${rotX}deg) rotateY(${rotY}deg) scale(${currentScale})`,
              transformStyle: "preserve-3d",
              transition: "none",
            }}
          >
            {p.isBill ? (
              <CashBill moneyColor={moneyColor} outlineColor={outlineColor} />
            ) : (
              <DollarSymbol moneyColor={moneyColor} outlineColor={outlineColor} />
            )}
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

export default MoneyExplosion;